begin;
create table kiyi_private.stage2_catalog_backup(key text primary key,definition text not null);
alter table kiyi_private.stage2_catalog_backup enable row level security;
revoke all on kiyi_private.stage2_catalog_backup from public,anon,authenticated;
create table public.kiyi_vehicle_models(id text primary key,name text not null,kind text not null check(kind in ('car','motorcycle')),body text not null,ready boolean not null default false,parts jsonb not null default '{}');
alter table public.kiyi_vehicle_models enable row level security;
create policy catalog_read on public.kiyi_vehicle_models for select to authenticated using(true);
grant select on public.kiyi_vehicle_models to authenticated;

alter table public.kiyi_appearance drop constraint kiyi_vehicle_model_allowlist;
alter table public.kiyi_appearance add constraint kiyi_vehicle_model_catalog_fk foreign key(vehicle_model) references public.kiyi_vehicle_models(id);
do $patch$
declare d text; old_guard text; new_guard text; old_name text;
begin
 select pg_get_functiondef('kiyi_private.command(text,jsonb)'::regprocedure) into d;
 old_guard := $txt$if prod is null or not (prod=any(array['bmw-3','audi-a3','mercedes-c','vw-golf','renault-clio','fiat-egea','toyota-corolla']))$txt$;
 new_guard := $txt$if prod is null or not exists(select 1 from public.kiyi_vehicle_models m where m.id=prod and m.kind='car' and m.ready)$txt$;
 old_name := $txt$case prod when 'bmw-3' then 'BMW 3 Serisi' when 'audi-a3' then 'Audi A3' when 'mercedes-c' then 'Mercedes C Serisi' when 'vw-golf' then 'Volkswagen Golf' when 'renault-clio' then 'Renault Clio' when 'fiat-egea' then 'Fiat Egea' when 'toyota-corolla' then 'Toyota Corolla' end$txt$;
 if position(old_guard in d)=0 or position(old_name in d)=0 then raise exception 'Current command differs; abort migration';end if;
 execute replace(replace(d,old_guard,new_guard),old_name,'(select name from public.kiyi_vehicle_models where id=prod)');
end $patch$;
commit;
